arguments.file_text:
@page "/catalog"
@using sv_443a4e03aa654d59bd3b81e5214b25c6.Services
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryLoad">Retry</button>
    </div>
}
else
{
    <div class="catalog-layout">
        @* ───── Left sidebar: filters ───── *@
        <aside class="catalog-sidebar">
            <h5>Filters</h5>

            @* Category filter *@
            <div class="mb-3">
                <label class="form-label fw-semibold">Categories</label>
                @if (categories is null)
                {
                    <p class="text-muted small">Loading…</p>
                }
                else
                {
                    @foreach (var cat in categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input"
                                   type="checkbox"
                                   id="@($"cat-{cat}")"
                                   checked="@(selectedCategories.Contains(cat))"
                                   @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                        </div>
                    }
                }
            </div>

            @* Price range *@
            <div class="mb-3">
                <label class="form-label fw-semibold">Price Range</label>
                <div class="d-flex gap-2">
                    <input type="number" class="form-control form-control-sm" placeholder="Min"
                           @bind="minPrice" min="0" step="0.01" />
                    <input type="number" class="form-control form-control-sm" placeholder="Max"
                           @bind="maxPrice" min="0" step="0.01" />
                </div>
            </div>

            @* In-stock toggle *@
            <div class="form-check mb-3">
                <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>

            <div class="d-grid gap-2">
                <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
                <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
            </div>
        </aside>

        @* ───── Main content area ───── *@
        <section class="catalog-main">
            @* Toolbar *@
            <div class="catalog-toolbar d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                <div class="d-flex align-items-center gap-2">
                    <label for="sortBy" class="form-label mb-0 text-nowrap">Sort by:</label>
                    <select id="sortBy" class="form-select form-select-sm" style="width: auto;" @bind="sortBy" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A–Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>

                @if (result is not null)
                {
                    <span class="text-muted small">
                        Showing @(StartItem)–@(EndItem) of @result.TotalCount products
                    </span>
                }
            </div>

            @* Content states *@
            @if (isLoading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading…</span>
                    </div>
                </div>
            }
            else if (result is null || result.Items.Count == 0)
            {
                <div class="text-center py-5 text-muted">
                    <h5>No products found</h5>
                    <p>Try adjusting your filters or clearing them.</p>
                </div>
            }
            else
            {
                @* Product grid *@
                <div class="product-grid">
                    @foreach (var product in result.Items)
                    {
                        <ProductCard Product="product"
                                     OnProductSelected="HandleProductSelected"
                                     OnAddToCart="HandleAddToCart" />
                    }
                </div>

                @* Pagination *@
                @if (TotalPages > 1)
                {
                    <nav aria-label="Product pagination" class="mt-4">
                        <ul class="pagination justify-content-center flex-wrap">
                            <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage - 1)" disabled="@(currentPage == 1)">Previous</button>
                            </li>
                            @foreach (var p in PageNumbers)
                            {
                                <li class="page-item @(p == currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
                                </li>
                            }
                            <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPage(currentPage + 1)" disabled="@(currentPage == TotalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </section>
    </div>
}

@code {
    /// <summary>Raised when a product card is clicked (not the Add to Cart button).</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private PagedResult<Product>? result;
    private bool isLoading = true;
    private string? errorMessage;

    // Computed helpers
    private int TotalPages => result is null || result.TotalCount == 0 ? 1 : (int)Math.Ceiling((double)result.TotalCount / PageSize);
    private int StartItem => result is null || result.TotalCount == 0 ? 0 : (currentPage - 1) * PageSize + 1;
    private int EndItem => result is null ? 0 : Math.Min(currentPage * PageSize, result.TotalCount);

    private IEnumerable<int> PageNumbers
    {
        get
        {
            int total = TotalPages;
            // Show a window of pages around the current page
            int start = Math.Max(1, currentPage - 2);
            int end = Math.Min(total, currentPage + 2);
            // Ensure at least 5 pages shown when available
            if (end - start < 4)
            {
                start = Math.Max(1, end - 4);
                end = Math.Min(total, start + 4);
            }
            return Enumerable.Range(start, end - start + 1);
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = categories is null ? ProductService.GetCategoriesAsync() : Task.FromResult(categories);
            var searchTask = ProductService.SearchAsync(BuildFilter(), sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            categories = await categoriesTask;
            result = await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter()
    {
        return new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadDataAsync();
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages || page == currentPage)
            return;
        currentPage = page;
        await LoadDataAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — wire up to a cart service as needed
        return Task.CompletedTask;
    }

    private async Task RetryLoad()
    {
        await LoadDataAsync();
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    background: #f8f9fa;
    border-radius: 0.5rem;
    padding: 1rem;
    align-self: flex-start;
    position: sticky;
    top: 1rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

@media (max-width: 768px) {
    .catalog-layout {
        flex-direction: column;
    }

    .catalog-sidebar {
        flex: none;
        max-width: 100%;
        position: static;
    }

    .product-grid {
        grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    }
}

